import lessons from './study-lessons.json';
import type { PracticeBank, PracticeExercise, ExercisePurpose } from './practice-types';

// These are authored offline exercises. Open work is reviewed by the learner;
// it is never treated as an automatically scored answer or certified skill.
type ObjectiveSpec = [title:string, prerequisite:string, misconception:string, cue:string];
type Task = {prompt:string;format:PracticeExercise['format'];answer?:number;acceptedAnswers?:string[];choices?:string[];reason:string;hint:string;rubric?:string[]};
const n=(prompt:string,answer:number,reason:string,hint:string):Task=>({prompt,answer,reason,hint,format:'number'});
const t=(prompt:string,answer:string,reason:string,hint:string):Task=>({prompt,acceptedAnswers:[answer],reason,hint,format:'text'});
const c=(prompt:string,choices:string[],answer:number,reason:string,hint:string):Task=>({prompt,choices,answer,reason,hint,format:'choice'});
const r=(prompt:string,reason:string,rubric:string[],hint:string):Task=>({prompt,reason,rubric,hint,format:'rubric'});
const purposes:ExercisePurpose[]=['example','guided','independent','review','guided','independent','transfer','review','guided','independent','application','review','guided','independent','application','review'];
const commonCode=['The result satisfies the stated input/output contract.','The explanation follows the actual execution order.','A normal case and the stated boundary case are checked.'];
const code=(prompt:string,reason:string,hint:string,criteria:string[]=commonCode)=>r(prompt,reason,criteria,hint);
const design=(prompt:string,reason:string,criteria:string[],hint:string)=>r(prompt,reason,criteria,hint);
type ArtPack=[ObjectiveSpec,string[],[string,string][]];
const art=(topic:string,packs:ArtPack[])=>bank(topic,packs.map(p=>p[0]),packs.flatMap(p=>p[2].map(([prompt,model])=>r(`Studio self-review: ${prompt}`,model,p[1],`Start by checking: ${p[1][0]}`))));
const bank=(topicId:string,objectives:ObjectiveSpec[],tasks:Task[]):PracticeBank=>{
  const lesson=(lessons as Record<string,{explanation:string[];sources:{url:string}[]}>)[topicId];
  return {topicId,version:1,scope:lesson.explanation.join('\n\n'),reviewStatus:'awaiting-subject-review',sources:lesson.sources.map(s=>s.url),objectives:objectives.map((o,i)=>({id:`${topicId}-objective-${i+1}`,title:o[0],prerequisites:[o[1]],misconceptions:[o[2]]})),exercises:tasks.map((x,i)=>{
    const o=objectives[Math.floor(i/4)];
    return {id:`${topicId}-practice-${String(i+1).padStart(2,'0')}`,objectiveId:`${topicId}-objective-${Math.floor(i/4)+1}`,purpose:purposes[i],difficulty:i===6||i===13?'extension':'core',format:x.format,prompt:x.prompt,choices:x.choices,answer:x.answer,acceptedAnswers:x.acceptedAnswers,hints:[o[3],x.hint],solution:x.format==='rubric'?[{step:x.reason,why:o[3]},{step:`Review evidence for: ${x.rubric?.join(' ')}`,why:`This checks the stated ${o[0].toLowerCase()} goal and helps detect the misconception: ${o[2]}`}]:[{step:`${o[0]}: ${o[3]}`,why:x.hint},{step:`Result: ${x.format==='choice'?x.choices?.[x.answer!]:x.answer??x.acceptedAnswers?.[0]}.`,why:x.reason}],mistakes:x.format==='choice'?x.choices!.flatMap((_,j)=>j===x.answer?[]:[{answer:String(j),feedback:x.reason}]):[{answer:'Common mistake',feedback:`${o[2]} ${x.reason}`}],rubric:x.rubric};
  })};
};

